CREATE TYPE "FinanceWorkspaceStatus" AS ENUM ('Draft','Active','Reconciliation','ClosePending','Closed','Archived');
CREATE TYPE "FinanceLineType" AS ENUM ('Revenue','DirectCost','IndirectCost','LabourCost','AssetCost','LogisticsCost','Recovery','Tax');
CREATE TYPE "FinanceValueStage" AS ENUM ('Estimate','Budget','Baseline','Forecast','Commitment','Actual','Accrual','Billing','Cash');
CREATE TYPE "FinanceVersionStatus" AS ENUM ('Draft','Submitted','Approved','Superseded','Locked','Rejected');
CREATE TYPE "FinanceCommitmentStatus" AS ENUM ('Draft','Approved','Ordered','PartiallyInvoiced','FullyInvoiced','Settled','Cancelled');
CREATE TYPE "FinanceInvoiceStatus" AS ENUM ('Draft','Approved','Issued','PartiallyPaid','Paid','Overdue','Disputed','Credited','Cancelled');
CREATE TYPE "FinancePaymentDirection" AS ENUM ('Receipt','Disbursement','Refund');
CREATE TYPE "FinancePaymentStatus" AS ENUM ('Planned','PendingApproval','Approved','Submitted','Cleared','Failed','Reversed');
CREATE TYPE "FinanceReconciliationStatus" AS ENUM ('Open','Investigating','Resolved','Approved');
CREATE TYPE "FinanceCloseStatus" AS ENUM ('Open','ReadyForReview','Approved','Reopened');

CREATE TABLE "EventFinanceWorkspace" ("id" TEXT NOT NULL,"systemNumber" SERIAL NOT NULL,"organizationId" TEXT NOT NULL,"eventId" TEXT NOT NULL,"currency" TEXT NOT NULL DEFAULT 'ZAR',"status" "FinanceWorkspaceStatus" NOT NULL DEFAULT 'Draft',"profitabilityPolicy" JSONB,"statutorySystemName" TEXT,"statutoryExternalId" TEXT,"createdByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"closedAt" TIMESTAMP(3),"archivedAt" TIMESTAMP(3),CONSTRAINT "EventFinanceWorkspace_pkey" PRIMARY KEY("id"));
CREATE TABLE "EventFinanceOwner" ("id" TEXT NOT NULL,"financeWorkspaceId" TEXT NOT NULL,"role" TEXT NOT NULL,"ownerUserId" TEXT NOT NULL,"effectiveFrom" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"effectiveTo" TIMESTAMP(3),"assignedByUserId" TEXT NOT NULL,CONSTRAINT "EventFinanceOwner_pkey" PRIMARY KEY("id"));
CREATE TABLE "FinanceWbsNode" ("id" TEXT NOT NULL,"financeWorkspaceId" TEXT NOT NULL,"parentId" TEXT,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"costCentre" TEXT,"profitCentre" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"sequence" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "FinanceWbsNode_pkey" PRIMARY KEY("id"));
CREATE TABLE "EventFinancialLine" ("id" TEXT NOT NULL,"financeWorkspaceId" TEXT NOT NULL,"wbsNodeId" TEXT NOT NULL,"requirementItemId" TEXT,"lineType" "FinanceLineType" NOT NULL,"stage" "FinanceValueStage" NOT NULL,"description" TEXT NOT NULL,"quantity" DOUBLE PRECISION NOT NULL DEFAULT 1,"unitAmount" DOUBLE PRECISION NOT NULL,"amountExcludingTax" DOUBLE PRECISION NOT NULL,"taxAmount" DOUBLE PRECISION NOT NULL DEFAULT 0,"totalAmount" DOUBLE PRECISION NOT NULL,"currency" TEXT NOT NULL,"sourceModule" TEXT NOT NULL,"sourceType" TEXT NOT NULL,"sourceId" TEXT NOT NULL,"externalAccountingId" TEXT,"occurredAt" TIMESTAMP(3),"approvedByUserId" TEXT,"approvedAt" TIMESTAMP(3),"reversedByLineId" TEXT,"createdByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "EventFinancialLine_pkey" PRIMARY KEY("id"));
CREATE TABLE "EventBudgetVersion" ("id" TEXT NOT NULL,"financeWorkspaceId" TEXT NOT NULL,"version" INTEGER NOT NULL,"versionType" TEXT NOT NULL,"status" "FinanceVersionStatus" NOT NULL DEFAULT 'Draft',"description" TEXT,"effectiveAt" TIMESTAMP(3),"submittedByUserId" TEXT,"submittedAt" TIMESTAMP(3),"approvedByUserId" TEXT,"approvedAt" TIMESTAMP(3),"lockedByUserId" TEXT,"lockedAt" TIMESTAMP(3),"createdByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "EventBudgetVersion_pkey" PRIMARY KEY("id"));
CREATE TABLE "EventBudgetLine" ("id" TEXT NOT NULL,"budgetVersionId" TEXT NOT NULL,"wbsNodeId" TEXT NOT NULL,"requirementItemId" TEXT,"lineType" "FinanceLineType" NOT NULL,"description" TEXT NOT NULL,"amount" DOUBLE PRECISION NOT NULL,"currency" TEXT NOT NULL,"sourceType" TEXT,"sourceId" TEXT,"changeReason" TEXT,CONSTRAINT "EventBudgetLine_pkey" PRIMARY KEY("id"));
CREATE TABLE "EventFinancialChange" ("id" TEXT NOT NULL,"financeWorkspaceId" TEXT NOT NULL,"changeType" TEXT NOT NULL,"sourceModule" TEXT NOT NULL,"sourceType" TEXT NOT NULL,"sourceId" TEXT NOT NULL,"description" TEXT NOT NULL,"revenueImpact" DOUBLE PRECISION NOT NULL DEFAULT 0,"costImpact" DOUBLE PRECISION NOT NULL DEFAULT 0,"marginImpact" DOUBLE PRECISION NOT NULL DEFAULT 0,"forecastImpact" DOUBLE PRECISION NOT NULL DEFAULT 0,"status" "FinanceVersionStatus" NOT NULL DEFAULT 'Draft',"requestedByUserId" TEXT NOT NULL,"requestedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"approvedByUserId" TEXT,"approvedAt" TIMESTAMP(3),"rejectionReason" TEXT,CONSTRAINT "EventFinancialChange_pkey" PRIMARY KEY("id"));
CREATE TABLE "EventFinanceCommitment" ("id" TEXT NOT NULL,"financeWorkspaceId" TEXT NOT NULL,"requirementItemId" TEXT,"supplierId" TEXT NOT NULL,"commercialAwardId" TEXT,"purchaseOrderId" TEXT,"description" TEXT NOT NULL,"amountExcludingTax" DOUBLE PRECISION NOT NULL,"taxAmount" DOUBLE PRECISION NOT NULL DEFAULT 0,"totalAmount" DOUBLE PRECISION NOT NULL,"currency" TEXT NOT NULL,"status" "FinanceCommitmentStatus" NOT NULL DEFAULT 'Draft',"budgetLineId" TEXT,"approvedByUserId" TEXT,"approvedAt" TIMESTAMP(3),"committedAt" TIMESTAMP(3),"cancelledAt" TIMESTAMP(3),"cancellationReason" TEXT,"externalAccountingId" TEXT,"createdByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "EventFinanceCommitment_pkey" PRIMARY KEY("id"));
CREATE TABLE "EventClientInvoice" ("id" TEXT NOT NULL,"systemNumber" SERIAL NOT NULL,"financeWorkspaceId" TEXT NOT NULL,"contactId" TEXT NOT NULL,"invoiceNumber" TEXT NOT NULL,"status" "FinanceInvoiceStatus" NOT NULL DEFAULT 'Draft',"issueDate" TIMESTAMP(3),"dueDate" TIMESTAMP(3),"currency" TEXT NOT NULL,"subtotal" DOUBLE PRECISION NOT NULL,"taxAmount" DOUBLE PRECISION NOT NULL DEFAULT 0,"totalAmount" DOUBLE PRECISION NOT NULL,"paidAmount" DOUBLE PRECISION NOT NULL DEFAULT 0,"balanceAmount" DOUBLE PRECISION NOT NULL,"contractReference" TEXT,"externalAccountingId" TEXT,"approvedByUserId" TEXT,"approvedAt" TIMESTAMP(3),"issuedAt" TIMESTAMP(3),"createdByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "EventClientInvoice_pkey" PRIMARY KEY("id"));
CREATE TABLE "EventClientInvoiceLine" ("id" TEXT NOT NULL,"invoiceId" TEXT NOT NULL,"requirementItemId" TEXT,"description" TEXT NOT NULL,"quantity" DOUBLE PRECISION NOT NULL,"unitPrice" DOUBLE PRECISION NOT NULL,"taxAmount" DOUBLE PRECISION NOT NULL DEFAULT 0,"totalAmount" DOUBLE PRECISION NOT NULL,"sourceType" TEXT NOT NULL,"sourceId" TEXT NOT NULL,CONSTRAINT "EventClientInvoiceLine_pkey" PRIMARY KEY("id"));
CREATE TABLE "EventFinancePayment" ("id" TEXT NOT NULL,"financeWorkspaceId" TEXT NOT NULL,"invoiceId" TEXT,"commitmentId" TEXT,"direction" "FinancePaymentDirection" NOT NULL,"status" "FinancePaymentStatus" NOT NULL DEFAULT 'Planned',"amount" DOUBLE PRECISION NOT NULL,"currency" TEXT NOT NULL,"plannedDate" TIMESTAMP(3),"submittedAt" TIMESTAMP(3),"clearedAt" TIMESTAMP(3),"bankReference" TEXT,"externalAccountingId" TEXT,"approvedByUserId" TEXT,"approvedAt" TIMESTAMP(3),"createdByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "EventFinancePayment_pkey" PRIMARY KEY("id"));
CREATE TABLE "EventFinanceReconciliation" ("id" TEXT NOT NULL,"financeWorkspaceId" TEXT NOT NULL,"reconciliationType" TEXT NOT NULL,"sourceModule" TEXT NOT NULL,"sourceType" TEXT NOT NULL,"sourceId" TEXT NOT NULL,"expectedAmount" DOUBLE PRECISION NOT NULL,"recordedAmount" DOUBLE PRECISION NOT NULL,"varianceAmount" DOUBLE PRECISION NOT NULL,"status" "FinanceReconciliationStatus" NOT NULL DEFAULT 'Open',"explanation" TEXT,"evidence" JSONB,"resolvedByUserId" TEXT,"resolvedAt" TIMESTAMP(3),"approvedByUserId" TEXT,"approvedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "EventFinanceReconciliation_pkey" PRIMARY KEY("id"));
CREATE TABLE "EventFinanceCloseItem" ("id" TEXT NOT NULL,"financeWorkspaceId" TEXT NOT NULL,"closeType" TEXT NOT NULL,"criteria" TEXT NOT NULL,"status" "FinanceCloseStatus" NOT NULL DEFAULT 'Open',"evidence" JSONB,"completedByUserId" TEXT,"completedAt" TIMESTAMP(3),"approvedByUserId" TEXT,"approvedAt" TIMESTAMP(3),"reopenedByUserId" TEXT,"reopenedAt" TIMESTAMP(3),"reopenReason" TEXT,CONSTRAINT "EventFinanceCloseItem_pkey" PRIMARY KEY("id"));
CREATE TABLE "EventFinanceAudit" ("id" TEXT NOT NULL,"financeWorkspaceId" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT NOT NULL,"action" TEXT NOT NULL,"previousValue" JSONB,"newValue" JSONB,"reason" TEXT,"sourceModule" TEXT NOT NULL,"sourceReference" TEXT,"userId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "EventFinanceAudit_pkey" PRIMARY KEY("id"));

