ALTER TABLE "EventFinancialLine" ADD CONSTRAINT "EventFinancialLine_financeWorkspaceId_fkey" FOREIGN KEY("financeWorkspaceId") REFERENCES "EventFinanceWorkspace"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "EventFinancialLine" ADD CONSTRAINT "EventFinancialLine_wbsNodeId_fkey" FOREIGN KEY("wbsNodeId") REFERENCES "FinanceWbsNode"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
