ALTER TABLE "EventFinancialChange" ADD CONSTRAINT "EventFinancialChange_financeWorkspaceId_fkey" FOREIGN KEY("financeWorkspaceId") REFERENCES "EventFinanceWorkspace"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "EventFinanceCommitment" ADD CONSTRAINT "EventFinanceCommitment_financeWorkspaceId_fkey" FOREIGN KEY("financeWorkspaceId") REFERENCES "EventFinanceWorkspace"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "EventClientInvoice" ADD CONSTRAINT "EventClientInvoice_financeWorkspaceId_fkey" FOREIGN KEY("financeWorkspaceId") REFERENCES "EventFinanceWorkspace"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "EventClientInvoiceLine" ADD CONSTRAINT "EventClientInvoiceLine_invoiceId_fkey" FOREIGN KEY("invoiceId") REFERENCES "EventClientInvoice"("id") ON DELETE CASCADE ON UPDATE CASCADE;
